import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createBlankPuzzle, serializePuzzle } from '../../lib/puzzle-storage';

// Story 23-S3 — no username, no privileges. Every server action in this
// module, called directly (as any client can call a server action), refuses
// a valid session whose account has no username exactly as it refuses no
// session: it sends the browser to / before reading or writing anything.
// The actions are enumerated from the module itself, so an action added
// later is checked too. A named session is still served (the control).
// Do not edit this file to match an implementation.

const mocks = vi.hoisted(() => ({
  getSession: vi.fn(),
  headers: vi.fn(),
  revalidatePath: vi.fn(),
  data: vi.fn(),
}));

vi.mock('@/lib/auth', () => ({ auth: { api: { getSession: mocks.getSession } } }));
vi.mock('next/headers', () => ({ headers: mocks.headers }));
vi.mock('next/navigation', () => ({
  redirect: (path: string) => { throw new Error(`redirect:${path}`); },
  notFound: () => { throw new Error('notFound'); },
}));
vi.mock('next/cache', () => ({ revalidatePath: mocks.revalidatePath }));
vi.mock('@/lib/prisma', () => {
  // Any model, any method, and $transaction: every data access lands in one spy.
  const model = new Proxy({}, { get: () => mocks.data });
  const prisma = new Proxy({}, { get: (_target, key) => (String(key).startsWith('$') ? mocks.data : model) });
  return { prisma };
});

import * as actions from './actions';

const stored = serializePuzzle(createBlankPuzzle('mini'));
const requestHeaders = new Headers({ cookie: 'better-auth.session_token=token' });

/** The actions this story enumerated on main; the module may add more, never lose these.
 *  Amended by 24-S3: the snapshot saves (`saveGrid`, `saveHints`, `saveTitle`),
 *  the snapshot `enterHints` and `publishPuzzle` are removed, replaced by
 *  `commitOperation` and `publishAtVersion` (epic 24), which are listed. */
const KNOWN_ACTIONS = [
  'loadPlayPuzzle', 'startPlaySession', 'resetPlaySession', 'savePlayEntries',
  'inspectPlayCompletion', 'createPuzzle', 'listPuzzles', 'commitOperation',
  'publishAtVersion', 'setPuzzleVisibility', 'duplicatePuzzle',
  'deletePuzzle', 'loadPuzzle',
];

/** Plausible arguments for each known action; any other action gets generic ones. */
const ARGS: Record<string, unknown[]> = {
  loadPlayPuzzle: ['existing'],
  startPlaySession: ['existing'],
  resetPlaySession: ['existing', 'play-session'],
  savePlayEntries: ['existing', stored.grid],
  inspectPlayCompletion: ['existing'],
  createPuzzle: [{ title: 'Gate', size: 'mini' }],
  listPuzzles: [],
  commitOperation: [{ opId: 'op', puzzleId: 'existing', clientId: 'tab', epoch: 0, baseVersion: 0, kind: 'title', title: 'Changed' }],
  publishAtVersion: [{ puzzleId: 'existing', version: 0, visibility: 'public' }],
  setPuzzleVisibility: ['existing', 'public'],
  duplicatePuzzle: ['existing'],
  deletePuzzle: ['existing'],
  loadPuzzle: ['existing'],
};

type AnyAction = (...args: unknown[]) => Promise<unknown>;
const exported = (Object.entries(actions) as Array<[string, unknown]>)
  .filter((entry): entry is [string, AnyAction] => typeof entry[1] === 'function');

function sessionFor(displayName: unknown) {
  return {
    user: { id: 'nameless', email: 'nameless@example.test', name: 'Link Name', displayName },
    session: { id: 'valid', userId: 'nameless' },
  };
}

beforeEach(() => {
  vi.resetAllMocks();
  mocks.headers.mockResolvedValue(requestHeaders);
  mocks.data.mockResolvedValue(null);
});

describe('23-S3-U5 every puzzle action refuses an account without a username', () => {
  it('the module still exports every action this story enumerated', () => {
    expect(exported.map(([name]) => name)).toEqual(expect.arrayContaining(KNOWN_ACTIONS));
  });

  for (const [label, displayName] of [['null', null], ['empty', ''], ['whitespace-only', ' \t ']] as const) {
    it.each(exported)(`%s refuses a session whose username is ${label}, before any data access`, async (name, action) => {
      mocks.getSession.mockResolvedValue(sessionFor(displayName));
      await expect(action(...(ARGS[name] ?? ['existing', 'existing']))).rejects.toThrow(/^redirect:\/$/);
      expect(mocks.getSession).toHaveBeenCalledWith({ headers: requestHeaders });
      expect(mocks.data).not.toHaveBeenCalled();
      expect(mocks.revalidatePath).not.toHaveBeenCalled();
    });
  }
});

describe('23-S3-U6 a named account is still served (control)', () => {
  it('createPuzzle writes for a session with a username', async () => {
    mocks.getSession.mockResolvedValue({
      user: { id: 'named', email: 'named@example.test', name: '', displayName: 'Ada' },
      session: { id: 'valid', userId: 'named' },
    });
    mocks.data.mockResolvedValue({ id: 'created' });
    await expect(actions.createPuzzle({ title: 'Gate', size: 'mini' })).resolves.toEqual({ id: 'created' });
    expect(mocks.data).toHaveBeenCalledOnce();
    expect(mocks.data.mock.calls[0][0]).toEqual({ data: expect.objectContaining({ builderId: 'named', title: 'Gate' }) });
  });

  it('listPuzzles reads for a session with a username', async () => {
    mocks.getSession.mockResolvedValue({
      user: { id: 'named', email: 'named@example.test', name: '', displayName: 'Ada' },
      session: { id: 'valid', userId: 'named' },
    });
    mocks.data.mockResolvedValue([]);
    await expect(actions.listPuzzles()).resolves.toEqual([]);
    expect(mocks.data).toHaveBeenCalledOnce();
  });
});
